MultiLanguageItemData['de'][62552] = {name = "Glückskarte", additional_info = "[q]\"Vielleicht habt Ihr mit einer anderen Weissagung mehr Glück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62553] = {name = "Glückskarte", additional_info = "[q]\"Haltet Euch von eigenartigem Fleisch fern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62554] = {name = "Glückskarte", additional_info = "[q]\"Ihr hättet diese Spinne wirklich plündern sollen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62555] = {name = "Glückskarte", additional_info = "[q]\"Traut niemals einem ehrlichen Goblin oder einem nüchternen Zwerg.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62556] = {name = "Glückskarte", additional_info = "[q]\"Man weiß es nie genau, bis man plündert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62557] = {name = "Glückskarte", additional_info = "[q]\"Es wird Regen geben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62558] = {name = "Glückskarte", additional_info = "[q]\"Ihr werdet das Klimpern goldener Münzen hören.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62559] = {name = "Glückskarte", additional_info = "[q]\"Vertraut auf das Licht, aber behaltet Euer Reittier im Auge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62560] = {name = "Glückskarte", additional_info = "[q]\"Steht nie im Schatten von Drachen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62561] = {name = "Glückskarte", additional_info = "[q]\"Der Weg zum Schwarzfels ist mit guten Absichten gepflastert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62562] = {name = "Glückskarte", additional_info = "[q]\"Viele Schlachtzugwipes liegen in nächster Zukunft.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62563] = {name = "Glückskarte", additional_info = "[q]\"Epics sind wie Kinder: die der anderen sind nie so wundervoll wie Eure.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62564] = {name = "Glückskarte", additional_info = "[q]\"Erfahrung, Ehrenpunkte und Fraktionsruf liegen in den kommenden Tagen vor Euch.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62565] = {name = "Glückskarte", additional_info = "[q]\"Euer größtes Glück sind die Freunde, die Ihr habt. Besonders Tanks.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62566] = {name = "Glückskarte", additional_info = "[q]\"Die Zukunft sieht kataklysmisch aus.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62567] = {name = "Glückskarte", additional_info = "[q]\"Entdeckt die Schönheit des Gewöhnlichen. Und dann verkauft es für Bares an einen Händler.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62568] = {name = "Glückskarte", additional_info = "[q]\"Wer ein Blind Date verspricht, ist beim Aufreißen gebunden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62569] = {name = "Glückskarte", additional_info = "[q]\"Der Segen eines Schamanen ist elementar.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62570] = {name = "Glückskarte", additional_info = "[q]\"Eure Zukunft sieht rosig aus. Außer Ihr lauft Todesschwinge über den Weg.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62571] = {name = "Glückskarte", additional_info = "[q]\"Eure Chancen, in naher Zukunft eine 100 zu würfeln, stehen nicht schlecht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62572] = {name = "Glückskarte", additional_info = "\"Ihr werdet beim Angeln ein tiefes Gefühl von Entspannung (und Geduld) empfinden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62573] = {name = "Glückskarte", additional_info = "[q]\"Eines Tages werdet Ihr Euch dieses Reittier leisten können.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62574] = {name = "Glückskarte", additional_info = "[q]\"ZEIT, NACHZUBESTELLEN! Um mehr Weissagungen zu erhalten, schreibt an F.B. Krazzlestix, Bilgewässer Hafen. Mengenrabatte sind zu günstigen Konditionen erhältlich.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62575] = {name = "Glückskarte", additional_info = "[q]\"Ihr habt viele verborgene Talente. Mit mehr Erfahrung werdet Ihr noch mehr hinzugewinnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62576] = {name = "Glückskarte", additional_info = "[q]\"Wer eine ganze Armee bekämpft, ist ein Märtyrer; Wer gegen fünf auf einmal kämpft, ist die Elite.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62577] = {name = "Glückskarte", additional_info = "[q]\"Ein leichtes Herz trägt Euch durch schlechte Schlachtfelder.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62578] = {name = "Glückskarte", additional_info = "[q]\"All Eure Mühen sind die Reparaturkosten wert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62579] = {name = "Glückskarte", additional_info = "[q]\"Vertraut niemals einem Troll. Und auch keinem Schurken. Besonders keinem Trollschurken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62580] = {name = "Glückskarte", additional_info = "[q]\"Ungläubigkeit zerstört die Magie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62581] = {name = "Glückskarte", additional_info = "[q]\"Die Gelegenheit ist günstig, etwas neues zu probieren. Vielleicht einen neuen Beruf.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62582] = {name = "Glückskarte", additional_info = "[q]\"Jede Pflanze blüht dann auf, wenn die Zeit reif ist. Und dann pflückt Ihr sie!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62583] = {name = "Glückskarte", additional_info = "[q]\"Geht und ruht Euch aus. Ihr habt es Euch verdient. Aber vergesst nicht, in einem Gasthaus auszuruhen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62584] = {name = "Glückskarte", additional_info = "[q]\"Wer einen Wipe erwartet, wird nie enttäuscht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62585] = {name = "Glückskarte", additional_info = "[q]\"Seht niemals nach oben, wenn fliegende Reittiere über Euch sind.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62586] = {name = "Glückskarte", additional_info = "[q]\"Ihr werdet eine große Summe Geld erben. Ihr werdet alles im Auktionshaus verpulvern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62587] = {name = "Glückskarte", additional_info = "[q]\"Jemand in Eurem näheren Umkreis möchte mit Euch /flirten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62588] = {name = "Glückskarte", additional_info = "[q]\"Eure Talente werden anerkannt und belohnt. Wenn Eure Talentverteilung gut ist, natürlich.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62589] = {name = "Glückskarte", additional_info = "[q]\"Hilfe! Ich werde in einer Glückskeksfabrik gefangengehalten!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62590] = {name = "Glückskarte", additional_info = "[q]\"Morgen wird die Sonne scheinen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62591] = {name = "Glückskarte", additional_info = "[q]\"Ihr werdet ein Geschenk von jemandem erhalten, den Ihr verabscheut.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62592] = {name = "Verkohlte Hochlandbirke", additional_info = "Questgegenstand\n[q]\"Dieses verbrannte Holz verströmt einen unverwechselbaren Geruch. Kein Wunder, dass die Greifen so leicht darauf reagieren.\""}
