MultiLanguageItemData['de'][62597] = {name = "Troggwerkzeug", additional_info = "Questgegenstand\n[q]\"Ein Stein.\""}
MultiLanguageItemData['de'][62598] = {name = "Glückskarte", additional_info = "[q]\"Der Beginn aller Weisheit ist das Verlangen nach ihr. Der Weisheit letzter Schluss ist Theorycrafting.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62599] = {name = "Glückskarte", additional_info = "[q]\"Ihr werdet ein langes, glückliches Leben mit vielen Wiederbelebungen darin haben.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62600] = {name = "Glückskarte", additional_info = "[q]\"Der Weg des Facerollers ist nicht der Weg des Weisen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62601] = {name = "Glückskarte", additional_info = "[q]\"Es ist nicht alles Gold, was glänzt. Aber meistens könnt Ihr es für Gold verkaufen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62602] = {name = "Glückskarte", additional_info = "[q]\"Ihr teilt gern Eure Weisheit. Wenn Ihr so weitermacht, bleibt Euch nicht viel.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62603] = {name = "Glückskarte", additional_info = "[q]\"Wenn das Leben Euch Zitronen gibt, bezahlt die Reparaturkosten.\"\nVerkaufspreis:"}
