MultiLanguageItemData['de'][79513] = {name = "Glyphe 'Gedankenschinden'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Gedankenschinden' verringert das Bewegungstempo des Ziels nicht mehr. Stattdessen wird jedes Mal, wenn 'Gedankenschinden' Schaden verursacht, Euer Bewegungstempo 5 Sek. lang um 15% erhöht. Dieser Effekt ist bis zu 3-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][79514] = {name = "Glyphe 'Schattenwort: Tod'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Schattenwort: Tod' kann jetzt jederzeit gewirkt werden, fügt Zielen mit über 20% Gesundheit jedoch nur 25% des Schadens zu [ Gedankenschinden : und erzeugt beim Einsatz gegen sie keine Schattenkugeln mehr ].\n\n Das Wirken von 'Schattenwort: Tod' fügt Euch nun Schaden in Höhe des Schadens zu, den der Zauber einem Gegner mit mehr als 20% Gesundheit zufügen würde.\nVerkaufspreis:"}
MultiLanguageItemData['de'][79515] = {name = "Glyphe 'Vampirumarmung'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Zauber 'Vampirumarmung' wandelt zusätzliche 50% Eures verursachten Schadens in Heilung um, die Gesamtdauer des Effekts wird jedoch um 5 Sek. verringert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][79538] = {name = "Glyphe 'Jindujun'", additional_info = "[q9]Geringe Glyphe\nKlassen: Priester\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nZiele Eures Zaubers 'Levitieren' reiten nun während der Effektdauer auf einer Wolke."}
