MultiLanguageItemData['de'][84122] = {name = "Rezept: Fläschchen des Alchemisten", additional_info = "BenötigtAlchemie\n(550)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens des Alchemisten\n\n\n[q3]Fläschchen des Alchemisten\nWird beim Aufheben gebunden\nBenötigtAlchemie\n(300)\n[q2]Benutzen: Erhöht Eure Beweglichkeit, Stärke oder Intelligenz 2 Stunden lang um 320 . Es wird stets Euer höchster Wert gewählt.\n\n Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n[q]\"Kann in Arenen verwendet werden. Dieses mächtige Fläschchen wird bei der Verwendung nicht verbraucht, profitiert jedoch nicht von Mixologie.\"\nBenötigt Kristallphiole , Eiskappe (7), Bergsilbersalbei (7), Geisterpilz (7)"}
MultiLanguageItemData['de'][84123] = {name = "Rezept: Fläschchen der Herbstblätter", additional_info = "BenötigtAlchemie\n(550)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Fläschchens der Herbstblätter.\n[q2]Beim Herstellen dieses Fläschchens besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\n Die Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\n\nFläschchen der Herbstblätter\nBenötigt Stufe 85\n[q2]Benutzen: Erhöht die Willenskraft 1 Stunde lang um 1000 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Teepflanze (4), Goldlotus"}
MultiLanguageItemData['de'][84124] = {name = "Rezept: Meisterlicher Heiltrank", additional_info = "BenötigtAlchemie\n(500)\n[q2]Benutzen: Lehrt Euch die Herstellung eines meisterlichen Heiltranks.\n[q2]Beim Herstellen dieses Gegenstands besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\n Die Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\n\nMeisterlicher Heiltrank\nBenötigt Stufe 85\n[q2]Benutzen: Stellt 120000 Gesundheit wieder her. (1 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Teepflanze"}
MultiLanguageItemData['de'][84125] = {name = "Rezept: Goldberyll transmutieren", additional_info = "BenötigtAlchemie\n(575)\n[q2]Benutzen: Lehrt Euch die Transmutation eines Goldberylls.\n[q2]Beim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\n Die Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\n\n[q3]Goldberyll\nVerkaufspreis: \nBenötigt Sonnenstein , Goldlotus"}
MultiLanguageItemData['de'][84126] = {name = "Rezept: Aragonit transmutieren", additional_info = "BenötigtAlchemie\n(575)\n[q2]Benutzen: Lehrt Euch die Transmutation eines Aragoniten.\n[q2]Beim Durchführen dieser Transmutation besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\n Die Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\n\n[q3]Aragonit\nVerkaufspreis: \nBenötigt Chiastolith , Goldlotus"}
MultiLanguageItemData['de'][84127] = {name = "Rezept: Verjüngung des Alchemisten", additional_info = "BenötigtAlchemie\n(500)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Verjüngung des Alchemisten\n[q2]Beim Herstellen dieses Tranks besteht eine Chance, dass Ihr andere Alchemierezepte aus Pandaria entdeckt.\n\n Auf diese Weise entdeckte Rezepte können weitere Rezepte enthüllen, wenn Ihr mit ihnen Gegenstände herstellt.\n\n\nVerjüngung des Alchemisten\nBenötigt Stufe 85\nBenötigtAlchemie\n(500)\n[q2]Benutzen: Stellt 120000 Gesundheit und 1 Mana wieder her. (1 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Kristallphiole , Teepflanze"}
MultiLanguageItemData['de'][84128] = {name = "Rezept: Entweihtes Öl", additional_info = "BenötigtAlchemie\n(550)\n[q2]Benutzen: Lehrt Euch die Herstellung von entweihtem Öl.\n[q2]Beim Herstellen dieses Öls besteht eine Chance, dass Ihr neue Rezepte erlernt.\n\n Die Anzahl der Rezepte, die Ihr erlernen könnt, hängt von Eurer Alchemiefähigkeitsstufe ab.\n\n\nEntweihtes Öl\n[q2]Benutzen: Trinkt die widerliche Flüssigkeit.\nVerkaufspreis: \nBenötigt Stachelfisch (3)"}
