MultiLanguageItemData['de'][86562] = {name = "[q3]Hopfling", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Hopfling beschwören oder wieder freigeben."}
MultiLanguageItemData['de'][86563] = {name = "[q3]Hohles Schilfrohr", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man einen Wasserschreiter beschwört.\n[q2]Mit Rechtsklick Euren Wasserschreiter beschwören oder wieder freigeben."}
MultiLanguageItemData['de'][86564] = {name = "[q3]Erfülltes Jadefragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Schleifer beschwört.\n[q2]Ihr könnt den Schleifer mit einem Rechtsklick beschwören und entlassen."}
MultiLanguageItemData['de'][86565] = {name = "[q3]Schlachthorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Schmettert ins Horn, was Gegner in einem Umkreis von 40 Metern anzieht. (2 Min Abklingzeit)\n[q]\"Wird von Yaungolspähern getragen, um im Falle eines Angriffs Verbündete zu alarmieren.\""}
MultiLanguageItemData['de'][86566] = {name = "[q3]Sammlerhandschuhe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Hände} {Stoff}\n9 Rüstung\nHaltbarkeit 20 / 20\nBenötigt Stufe 85\n[q2]Anlegen: Ermöglicht schnelleres Sammeln von Ressourcen in Pandaria.\n[q]\"Schützt gegen scharfkantige Steine und Dornen.\""}
MultiLanguageItemData['de'][86567] = {name = "[q3]Yaungolwindspiel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Benutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 50000 körperlichen Schaden zu und stößt sie 2 Sek. lang zu Boden. (2 Min Abklingzeit)\n[q]\"Wird von Yaungolmedizinmännern verwendet, um Wetteränderungen zu erahnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86568] = {name = "[q3]Handlanger Peins Messingkompass", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Setzt die Erinnerungen eines längst vergessenen Ersten Maats frei. (Procchance: 5%, 3Min. Abklingzeit) (2 Std. Abklingzeit)"}
MultiLanguageItemData['de'][86569] = {name = "[q3]Kristall des Wahnsinns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Stufe 85\n[q2]Benutzen: Erhöht 1 Stunde lang alle Werte um 500 . Zählt sowohl als Kampf- als auch als Wächterelixier. (15 Min Abklingzeit)\n[q]\"Es wirkt fast, als ob er Euch... anstarrt.\""}
MultiLanguageItemData['de'][86570] = {name = "[q3]Kiste mit entführten Welpen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Benutzen: Befreit die entführten Welpen, die 10 Min. lang für Euch kämpfen. (1 Stunde Abklingzeit)\n[q]\"...und sie essen Welpen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86571] = {name = "[q3]Kangs Bindungsstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Erfüllt Euch mit Stein und gewährt eine Chance, nach dem Töten eines Gegners diesen in Stein zu hüllen. (Procchance: 33%, 1Min. Abklingzeit) (1 Stunde Abklingzeit)\n[q]\"Die Steinbinder der Mogu nutzen diese runenverzierten Katalysatoren, um Fleisch in Stein zu verwandeln.\""}
MultiLanguageItemData['de'][86572] = {name = "[q3]Terrakottafragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Benutzen: Beschwört einen Terrakottakrieger, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n[q]\"Mit mächtiger Mogumagie erfüllt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86573] = {name = "[q3]Fragment des Abschlusssteins", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Verwandelt in eine Mogustatue und kann 5 Min. lang nicht als Ziel erfasst werden. (30 Min Abklingzeit)\n[q]\"Ein Fragment unbekannter Herkunft, das von uralter Magie erfüllt ist.\""}
MultiLanguageItemData['de'][86574] = {name = "[q3]Elixier des uralten Wissens", additional_info = "Accountgebunden\n[q2]Benutzen: Erhöht die erhaltene Erfahrung 1 Stunde lang um 300%. Funktioniert nicht bei Spielercharakteren über Stufe 84.\n[q]\"Ein leises Flüstern ist aus dem Fläschchen zu vernehmen.\""}
MultiLanguageItemData['de'][86575] = {name = "[q3]Kelch der Geheimnisse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Gebt Euch Eurem Zorn 10 Sek. lang hin. Während der Wirkungsdauer verwandelt Euch der nächste Todesstoß, den Ihr gegen einen Spielercharakter erzielt, 5.50 Sek. lang in einen Mogu. Als Mogu könnt Ihr keine anderen Aktionen ausführen, während Ihr den Gegner verhöhnt. (10 Min Abklingzeit)\n[q]\"Rituale, um die Leichen gefallener Feinde zu entweihen, waren in der Mogukultur weit verbreitet.\""}
MultiLanguageItemData['de'][86576] = {name = "[q3]Dynastie des Stahls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Benutzen: Beschwört einen Klingentornado, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n[q]\"Die Schwertkunst der Mantis ist ein sorgsam gehütetes Geheimnis.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86577] = {name = "[q3]Rute des Bernformens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Hüllt das Ziel in Bern und verhindert bis zu 1 Min. lang jegliche Handlung. Jeglicher Schaden zerbricht den Bern. Kann nicht gegen Spielercharaktere oder Ziele über Stufe 94 eingesetzt werden. (5 Min Abklingzeit)\n[q]\"Wird von den Bernwebern der Mantis verwendet, um Konstruktionen oder gehärteten Bern herzustellen.\""}
MultiLanguageItemData['de'][86578] = {name = "[q3]Siegel des ewigen Kriegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Stellt 6 Sek. lang alle 1 Sek. 15% der Gesundheit und des Manas wieder her. Jeglicher erlittene Schaden entfernt die Raserei. Kann nur in Pandaria verwendet werden. Unwirksam bei Spielercharakteren über Stufe 94. (5 Min Abklingzeit)\n[q]\"An Shek'zeers Elitewächter für treue Dienste verliehen.\""}
MultiLanguageItemData['de'][86579] = {name = "[q3]Abgefüllter Tornado", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Springt hoch in die Lüfte. Kann nur draußen verwendet werden. (2 Min Abklingzeit)\n[q]\"Die Mantid haben vor langer Zeit gelernt, die Winde Pandarias ihrer Kaiserin gefügig zu machen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86580] = {name = "[q3]Übergroßes Seerosenblatt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Priester , Todesritter , Schamane , Magier , Hexenmeister , Mönch\n[q2]Benutzen: Gewährt eine Druidenfähigkeit abhängig von der Klasse und der Kampfrolle. Kann nur in Pandaria verwendet werden. (1 Stunde Abklingzeit)\n[q]\"Ein ganzes Ökosystem liegt darin verborgen.\""}
MultiLanguageItemData['de'][86581] = {name = "[q3]Weitwassermuschelhorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit kleine Wassertropfen zu erzeugen. (10 Min Abklingzeit)\n[q]\"Das Muschelhorn ist mit Jinyurunen beschrieben, die es dem Benutzer ermöglichen, die Sprache der Wellen zu verstehen.\""}
MultiLanguageItemData['de'][86582] = {name = "[q3]Wasserjuwel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 85\n[q2]Benutzen: Erhöht das Schwimmtempo um 50% und gestattet 10 Min. lang Unterwasseratmung. (1 Stunde Abklingzeit)\n[q]\"Aus dem Schlund von Gokk'lok erbeutet.\""}
MultiLanguageItemData['de'][86583] = {name = "[q3]Schlachtbanner von Salyis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenötigt Stufe 85\n[q2]Benutzen: Versteckt sich 1 Sek. lang in den Schatten und beschwört einen Kriegsspäher von Salyis. Der Kriegsspäher zieht die Aufmerksamkeit von Monstern in der Nähe auf sich und rennt davon. (10 Min Abklingzeit)\n[q]\"Mit dem Blut vieler glückloser Abenteurer getränkt.\""}
MultiLanguageItemData['de'][86584] = {name = "[q3]Gehärteter Panzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Wirft einen harten Panzer, der das Ziel aus dem Sattel stößt. Funktioniert nicht bei Zielen über Stufe 94. (15 Min Abklingzeit)\n[q]\"Unfair!\""}
MultiLanguageItemData['de'][86585] = {name = "[q3]Goldenes Vlies", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Anlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n[q]\"Wird unter den Saurok als Zeichen von Reichtum und Status betrachtet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86586] = {name = "[q3]Pandarische Panflöte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Spielt auf der Panflöte, woraufhin Euch Kleintiere in der Nähe 15 Min. lang folgen. (1 Min Abklingzeit)"}
MultiLanguageItemData['de'][86587] = {name = "[q3]Samen des ruhigen Wachstums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenötigt Stufe 85\n[q2]Benutzen: Beschwört einen ruhigen Sprössling, der Euch 10 Min. lang heilt. (1 Stunde Abklingzeit)\n[q]\"Pulsierende Lebensenergie entspringt diesem Samen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86588] = {name = "[q3]Pandarischer Raketenzünder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Bereitet ein beeindruckendes Feuerwerk vor. (30 Min Abklingzeit)\n[q]\"Hier geht's ab!\""}
MultiLanguageItemData['de'][86589] = {name = "[q3]Ai-Lis Himmelsspiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Nehmt das etwas verzerrte Aussehen des Ziel an. Hält 10 Min. lang an. (1 Stunde Abklingzeit)\n[q]\"Von einem sich stetig bewegenden Wolkenring umgeben.\""}
MultiLanguageItemData['de'][86590] = {name = "[q3]Essenz der Brise", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Löst eine leichte Brise aus, die Eure Schritte leichter macht. Dieser Effekt zeigt nur in Pandaria Wirkung. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][86591] = {name = "[q3]Magische Banane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Wirft eine magische Banane auf den Boden, die die nächste Person zu Fall bringen wird, die über sie läuft. (2 Std. Abklingzeit)"}
MultiLanguageItemData['de'][86592] = {name = "[q3]Ho-zen-Friedenspfeife", additional_info = "Benötigt Stufe 90\n[q2]Benutzen: Erhöht den Ruf bei den Einwohnern Pandarias um 1000. (7 Tagen Abklingzeit)"}
MultiLanguageItemData['de'][86593] = {name = "[q3]Ho-zen-Strandball", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Macht Euch auf Sommerspaß gefasst! (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][86594] = {name = "[q3]Pfeife des hilfreichen Nupsi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Ruft das hilfreiche Nuspi, das für Euch nach Futter suchen und Geschenke zurückbringen wird. (2 Std. Abklingzeit)\n[q]\"Darauf wurde wohl heftig herumgekaut.\""}
MultiLanguageItemData['de'][86595] = {name = "[q2]Beutel mit hilfreichen Sachen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][86596] = {name = "[q3]Nats Angelstuhl", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Rechtsklicken, um einen bequemen Angelstuhl aufzustellen. (5 Min Abklingzeit)\n[q]\"Hat sogar einen Getränkehalter!\""}
MultiLanguageItemData['de'][86597] = {name = "[q2]Waffenkette aus lebendigem Stahl", additional_info = "Wird beim Anlegen gebunden\nBenötigt Stufe 85\n[q2]Benutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Eure Waffenkunde um 200 erhöht. Ist nicht mit ähnlichen Effekten stapelbar.\n\n Durch das Anbringen der Waffenkette wird der Gegenstand seelengebunden."}
