MultiLanguageItemData['de'][87746] = {name = "[q2]Bauplan: Verstärkte Retinarüstung", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung einer verstärkten Retinarüstung.\n\n\n[q4]Verstärkte Retinarüstung\nWird beim Aufheben gebunden\n{Kopf} {Platte}\n4191 Rüstung\n+855 Stärke\n+1.522 Ausdauer\n\n[q0]Metasockel\n[q0]Zahnradsockel\n[q0]Zahnradsockel\n[q0]Sockelbonus: + 180 Stärke\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 87\nBenötigt Ingenieurskunst (600)\nVerkaufspreis: \nBenötigt Lebendiger Stahl (6), Geistereisenbolzen (12)"}
MultiLanguageItemData['de'][87747] = {name = "[q2]Bauplan: Pulverfass des Schlossermeisters", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Pulverfasses des Schlossermeisters.\n\n\nPulverfass des Schlossermeisters\nBenötigt Ingenieurskunst (525)\n[q2]Benutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 450 im Schlossknacken benötigen.\nVerkaufspreis:\nBenötigt Einfaches Holz , Hochexplosives Schwarzpulver"}
MultiLanguageItemData['de'][87748] = {name = "[q2]Bauplan: Wassergleitjets", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung von Wassergleitjets.\n[q2]Bringt an einem Gürtel dauerhaft Wassergleitjets an, die es Euch gestatten, auf dem Wasser zu wandeln, und die Euer Schwimmtempo bis zu 12 Sek. lang erhöhen.\n\n Die Jets können nur einmal alle 30 Sek. eingesetzt werden und benötigen eine Ingenieursfertigkeit von mindestens 500."}
MultiLanguageItemData['de'][87750] = {name = "[q2]Bauplan: G91-Landhai", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines G91-Landhais.\n\n\nG91-Landhai\nBenötigt Stufe 85\n[q2]Benutzen: Fügt einem Gegner in bis zu 45 Metern Entfernung und Gegnern innerhalb von 10 Metern um das Hauptziel 37500 Feuerschaden zu. (1 Min Abklingzeit)\nBenötigt Geistereisenbolzen (2), Hochexplosives Schwarzpulver (2)"}
MultiLanguageItemData['de'][87751] = {name = "[q2]Bauplan: Goblinflammenwerfer - Nr. II", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Goblinflammenwerfers - Nr. II.\n\n\nGoblindrachengewehr - Nr. II\nBenötigt Stufe 85\n[q2]Benutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 4500 Naturschaden zufügt.\n\n Kann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Geistereisenbolzen (3), Hochexplosives Schwarzpulver (8)"}
MultiLanguageItemData['de'][87752] = {name = "[q2]Bauplan: Blingtron 4000", additional_info = "Benötigt Ingenieurskunst (600)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Blingtron 4000.\n\n\n[q4]Blingtron 4000\nWird beim Aufheben gebunden\nSpielzeug\nBenötigt Ingenieurskunst (600)\n[q2]Benutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Lebendiger Stahl (4), Trilliumbarren (4), Geistereisenbarren (4), Aragonit (4), Dioptas (4), Geist der Harmonie (4)"}
MultiLanguageItemData['de'][87753] = {name = "[q2]Bauplan: Nebeldurchdringende Brille", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung einer nebeldurchdringenden Brille.\n\n\n[q2]Nebeldurchdringende Brille\nWird beim Anlegen gebunden\nKopf\n[q2]Anlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n[q]\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\"\nVerkaufspreis: \nBenötigt Geistereisenbolzen (8), Geist der Harmonie (2)"}
MultiLanguageItemData['de'][87754] = {name = "[q2]Bauplan: Thermischer Amboss", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines thermischen Ambosses.\n\n\nThermischer Amboss\n[q2]Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\nBenötigt Hochexplosives Schwarzpulver (8), Geistereisenbolzen (6)"}
MultiLanguageItemData['de'][87755] = {name = "[q2]Bauplan: Wurmlochgenerator: Pandaria", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Wurmlochgenerator: Pandaria.\n\n\n[q3]Wurmlochgenerator: Pandaria\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst (500)\n[q2]Benutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt... (15 Min Abklingzeit)\n[q]\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\"\nVerkaufspreis:\nBenötigt Trilliumbarren (12), Geist der Harmonie (2)"}
MultiLanguageItemData['de'][87756] = {name = "[q2]Bauplan: Dampfgefüllter Ballon", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines dampfgefüllten Ballons."}
MultiLanguageItemData['de'][87757] = {name = "[q2]Bauplan: Geistereisendrachling", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Geistereisendrachlings.\n\n\n[q3]Geistereisendrachling\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q0]Zahnradsockel\n[q0]Zahnradsockel\n[q0]Zahnradsockel\n\nBenötigt Stufe 87\n[q2]Anlegen: Eure Angriffe haben eine Chance, einen Geistereisendrachling zu beschwören, der 20 Sek. lang an Eurer Seite kämpft. (Procchance: 25%, 1Min. Abklingzeit)\nVerkaufspreis: \nBenötigt Windwollstoff (12), Geistereisenbolzen (8), Hochexplosives Schwarzpulver (4)"}
MultiLanguageItemData['de'][87758] = {name = "[q2]Bauplan: Mechanischer Pandarendrachling", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines mechanischen Pandarendrachlings.\n\n\n[q3]Mechanischer Pandarendrachling\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren Welpling beschwören oder wieder freigeben.\nVerkaufspreis:\nBenötigt Geistereisenbarren (4), Trilliumbarren (6), Geist der Harmonie (2)"}
MultiLanguageItemData['de'][87759] = {name = "[q2]Bauplan: Großwildjäger", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Großwildjägers.\n\n\n[q3]Großwildjäger\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n{3,354 - 6,229 Schaden} {Tempo 2.80}\n(1,711 Schaden pro Sekunde)\n+449 Beweglichkeit\n+703 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 321.\n[q2]Erhöht Eure Tempowertung um + 283.\n\n[q0]Roter Sockel\n[q0]Sockelbonus: + 10 Beweglichkeit\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 85\nVerkaufspreis: \nBenötigt Geistereisenbolzen (12), Haarfeiner Sprengstoffauslöser , Schäftung aus Walnussholz , Verspiegeltes Zielfernrohr"}
MultiLanguageItemData['de'][87760] = {name = "[q2]Bauplan: Trilliumlangstreckenpräzisionsgewehr", additional_info = "Benötigt Ingenieurskunst (525)\n[q2]Benutzen: Lehrt Euch die Herstellung eines Trilliumlangstreckenpräzisionsgewehrs.\n\n\n[q3]Trilliumlangstreckenpräzisionsgewehr\nWird beim Anlegen gebunden\n{Distanz} {Schusswaffe}\n{5,704 - 10,595 Schaden} {Tempo 2.80}\n(2,911 Schaden pro Sekunde)\n+717 Beweglichkeit\n+1.195 Ausdauer\n[q2]Erhöht Eure Trefferwertung um + 435.\n[q2]Erhöht Eure Waffenkundewertung um + 546.\n\n[q0]Gelber Sockel\n[q0]Sockelbonus: + 10 Beweglichkeit\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 90\nVerkaufspreis: \nBenötigt Trilliumbarren (12), Haarfeiner Sprengstoffauslöser , Geist der Harmonie , Fürst von Schmetternichs Todeszielfernrohr"}
MultiLanguageItemData['de'][87761] = {name = "[q2]Bauplan: Rakete mit abgereichertem Kyparium", additional_info = "Benötigt Ingenieurskunst (600)\n[q2]Benutzen: Lehrt Euch die Herstellung einer Rakete mit abgereichertem Kyparium\n\n\n[q3]Rakete mit abgereichertem Kyparium\nEinzigartig\nReittier\nBenötigt Stufe 20\nBenötigtUnerfahrener Reiter\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nEine Höhepunkt goblinischer Ingenieurskunst! Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBenötigt Lebendiger Stahl (12), Kyparit (200), Kugel der Geheimnisse (3), Hochexplosives Schwarzpulver (12), Geist der Harmonie (12), Geistereisenbolzen (20)"}
