MultiLanguageItemData['de'][87880] = {name = "Glyphe 'Schlüpfriges Gebräu'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Ihr mit Eurer Fähigkeit 'Schlüpfriges Gebräu' einen Effekt entfernt, werdet Ihr um 10% Eurer maximalen Gesundheit geheilt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87881] = {name = "Glyphe 'Knisternder Tigerblitz'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eures Zaubers 'Knisternder Jadeblitz' hat nun die Farbe des Weißen Tigers.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87882] = {name = "Glyphe 'Fliegender Schlangentritt'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Fliegender Schlangentritt' endet automatisch, wenn Ihr einen Gegner trefft, wodurch der Flächenschadenseffekt und die Verlangsamung ausgelöst werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87883] = {name = "Glyphe 'Ehre'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr verbeugt Euch nach jedem erfolgreichen Einsatz von 'Berührung des Todes'.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87884] = {name = "Glyphe 'Hieb'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr greift immer mit Händen und Füßen an, wenn Ihr 'Hieb' einsetzt, selbst wenn Ihr keine Faustwaffen angelegt habt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87885] = {name = "Glyphe 'Springender Tigertritt'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nDer visuelle Effekt Eurer Fähigkeit 'Tritt der aufgehenden Sonne' hat nun die Farbe des Weißen Tigers.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87887] = {name = "Glyphe 'Geisterrolle'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' und 'Chitorpedo' einsetzen, während Ihr Euch tot in Geistergestalt bewegt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87888] = {name = "Glyphe 'Kampfstellung'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Geist erscheint nun in Kampfstellung, wenn Ihr 'Transzendenz' einsetzt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87889] = {name = "Glyphe 'Wasserrolle'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nIhr könnt 'Rollen' oder 'Chitorpedo' einsetzen, um Euch über Wasser fortzubewegen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87890] = {name = "Glyphe 'Zenflug'", additional_info = "[q9]Geringe Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Zenflug'. 'Zenflug' setzt voraus, dass Ihr eine Fluglizenz besitzt.\n\nZenflug\nIhr fliegt auf einer meditativen Wolke mit hoher Geschwindigkeit durch die Luft.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87891] = {name = "Glyphe 'Leben nach dem Tode'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nErhöht die Chance, eine heilende Sphäre zu erzeugen, wenn Ihr einen Gegner getötet habt, der Erfahrung oder Ehre gewährt, um 100%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87892] = {name = "Glyphe 'Furorfäuste'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWährend Ihr 'Furorfäuste' kanalisiert, ist Eure Parierchance um 100% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87893] = {name = "Glyphe 'Stärkendes Gebräu'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Stärkendes Gebräu' verringert Euren erlittenen Schaden um zusätzlich 5%, erhöht Eure Gesundheit dafür aber um 10% statt um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87894] = {name = "Glyphe 'Stieren des Ochsen'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nLehrt Euch den Zauber 'Stieren des Ochsen'.\n\nStieren des Ochsen\nEure Statue des Schwarzen Ochsen zieht den Hass des Ziels auf sich, verringert dessen Bewegungstempo um 50% und zwingt es, die Statue des Schwarzen Ochsen 8 Sek. lang anzugreifen. Die Statue muss sich innerhalb von 40 Metern vom Ziel befinden.\n\n Setzt voraus, dass Eure Statue des Schwarzen Ochsen aktiv ist.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87895] = {name = "Glyphe 'Lebenskokon'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Lebenskokon' kann nun auch gewirkt werden, wenn Ihr betäubt seid.\nVerkaufspreis:"}
MultiLanguageItemData['de'][87896] = {name = "Glyphe 'Glück im Unglück'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Mönch\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nWenn Eure Gesundheit unter 25% fällt, wird automatisch eine kostenlose heilende Sphäre neben Euch erzeugt. Dieser Effekt kann nur ein Mal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:"}
