MultiLanguageItemData['de'][88371] = {name = "[q2]Wassermelonenbombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+700 Ausdauer\n[q2]Anlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 1258 kritischen Trefferwert zu gewähren. (Procchance: 20%, 50s Abklingzeit)\n[q2]Benutzen: Wirft eine Wassermelone auf den Zielort, deren Aufprall alle Gegner in der Nähe mit klebrigem Fruchtfleisch bespritzt, was sie 3 Sek. lang bewegungsunfähig macht. Spielercharaktere sind davon nicht betroffen. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][88375] = {name = "Rübensandsack", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört 5 Min. lang einen Rübensandsack am Zielort, der als Zielattrappe dient.\n\n Kann nur im Freien von Pandaria eingesetzt werden. (1 Stunde Abklingzeit)\n[q]\"Eine Rübe mit extrem robustem Äußeren. Sie kann genauso gut Schläge einstecken wie ein Boss in heroischen Dungeons.\""}
MultiLanguageItemData['de'][88376] = {name = "[q2]Orange angemalte Rübe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 467.\n[q2]Anlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 1258 Meisterschaft zu gewähren. (Procchance: 20%, 50s Abklingzeit)\n[q2]Benutzen: Wirft eine orange angemalte Rübe auf den Zielort, worauf alle Shed-Ling in der Nähe 3 Sek. lang vor Furcht flüchten. (5 Min Abklingzeit)\nVerkaufspreis:"}
