MultiLanguageItemData['de'][92049] = {name = "Söldnervertrag: Magier", additional_info = "[q2]Benutzen: Heuert einen Magier an, der Hordespielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n 30 m Reichweite\n Sofort\n Requires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92050] = {name = "Söldnervertrag: Paladin", additional_info = "[q2]Benutzen: Heuert einen Paladin an, der Hordespielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht\n 30 m Reichweite\n Sofort\n Requires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 3000 erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92051] = {name = "Söldnervertrag: Priester", additional_info = "[q2]Benutzen: Heuert einen Priester an, der Hordespielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 m Reichweite Spontan\n Requires Priest\n Requires level 22 Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92052] = {name = "Söldnervertrag: Druide", additional_info = "[q2]Benutzen: Heuert einen Druiden an, der Hordespielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n 30 m Reichweite\n Sofort\n Requires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92053] = {name = "Söldnervertrag: Krieger", additional_info = "[q2]Benutzen: Heuert einen Krieger an, der Hordespielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n 30 m Reichweite\n Sofort\n Requires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92054] = {name = "Söldnervertrag: Schurke", additional_info = "[q2]Benutzen: Heuert einen Schurken an, der Hordespielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n 30 m Reichweite\n Sofort\n Requires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis."}
