MultiLanguageItemData['de'][92417] = {name = "Ausgrabungsbotfernsteuerung", additional_info = "Questgegenstand\n[q2]Benutzen: Ruft einen Ausgrabungsbot herbei, der an Eurer Seite kämpft. Funktioniert nur in der Krasarangwildnis. (1 Min Abklingzeit)\n[q]\"Mit diesem Gerät solltet ihr die Ausgrabungsbots im Steinbruch der Löwenlandung kontrollieren können. Die Betonung liegt hierbei auf \"solltet\"...\""}
MultiLanguageItemData['de'][92421] = {name = "Bewachungsvertrag: Friedhof", additional_info = "[q2]Benutzen: Heuert Wachen an, die einen eroberbaren Friedhof in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Friedhofs befinden und Eure Fraktion muss ihn kontrollieren."}
