MultiLanguageItemData['de'][92433] = {name = "Söldnervertrag: Schamane", additional_info = "[q2]Benutzen: Heuert einen Schamanen an, der Allianzspielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n 30 m Reichweite\n Sofort\n Requires Shaman\n Requires level 55 Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92434] = {name = "Söldnervertrag: Schurke", additional_info = "[q2]Benutzen: Heuert einen Schurken an, der Allianzspielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n 30 m Reichweite\n Sofort\n Requires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis."}
MultiLanguageItemData['de'][92435] = {name = "Söldnervertrag: Krieger", additional_info = "[q2]Benutzen: Heuert einen Krieger an, der Allianzspielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n 30 m Reichweite\n Sofort\n Requires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92436] = {name = "Söldnervertrag: Druide", additional_info = "[q2]Benutzen: Heuert einen Druiden an, der Allianzspielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n 30 m Reichweite\n Sofort\n Requires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92437] = {name = "Söldnervertrag: Priester", additional_info = "[q2]Benutzen: Heuert einen Priester an, der Allianzspielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 m Reichweite Spontan\n Requires Priest\n Requires level 22 Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92438] = {name = "Söldnervertrag: Paladin", additional_info = "[q2]Benutzen: Heuert einen Paladin an, der Allianzspielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht\n 30 m Reichweite\n Sofort\n Requires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 3000 erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92439] = {name = "Söldnervertrag: Magier", additional_info = "[q2]Benutzen: Heuert einen Magier an, der Allianzspielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n 30 m Reichweite\n Sofort\n Requires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92440] = {name = "Faksimile der Archäologischen Akademie", additional_info = "[q]\"Eine Abschrift der uralten Tafel der Korun. Darin wird der Ursprung der Götterglocke beschrieben.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][92441] = {name = "[q4]Kodex von Xerrath", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 90\n[q]\"Als Ihr das Buch aufhebt, erklingen schreckliche, geflüsterte Mysterien in Euren Ohren, die Euren Verstand peinigen…\""}
MultiLanguageItemData['de'][92442] = {name = "Banner der Horde", additional_info = "Einzigartig (20)\n[q2]Benutzen: Stellt ein Banner der Horde auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\n Ihr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Allianz können versuchen, Eure Banner niederzubrennen."}
MultiLanguageItemData['de'][92443] = {name = "Banner der Allianz", additional_info = "Einzigartig (20)\n[q2]Benutzen: Stellt ein Banner der Allianz auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\n Ihr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Horde können versuchen, Eure Banner niederzubrennen."}
