MultiLanguageItemData['de'][93205] = {name = "Pierre", additional_info = "[q2]Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\n[q]\"Ein raffinierter Herd. Für einen raffinierten Koch.\""}
