MultiLanguageItemData['de'][94525] = {name = "[q4]Gestohlenes Relikt von Zuldazar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Stolen Relic of Zuldazar] (1)\nSchmuck\n+1.467 Willenskraft\nBenötigt Stufe 90\n[q2]Anlegen: Eure hilfreichen Zauber haben eine Chance, Euch den Segen von Zuldazar zu gewähren. Dieser Effekt ist bis zu 6-mal stapelbar. (Ungefähr 2.89 Auslösungen pro Minute)\n[q2]Benutzen: Verbraucht alle Segen von Zuldazar, um das Ziel abzuschirmen, und absorbiert pro verbrauchtem Segen 9339 Schaden. Hält 15 Sek. lang an. (20 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94526] = {name = "[q4]Funken von Zandalar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Spark of Zandalar] (1)\nSchmuck\n[q2]Erhöht Eure Tempowertung um + 1.467.\nBenötigt Stufe 90\n[q2]Anlegen: Eure Angriffe haben eine Chance, Euch einen Funken von Zandalar zu gewähren. Sobald Ihr 10 dieser Funken angesammelt habt, verwandelt Ihr Euch 10 Sek. lang in einen Krieger der Zandalari. In dieser Gestalt ist Eure Stärke um 700 erhöht. (Ungefähr 11.10 Auslösungen pro Minute)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94527] = {name = "[q4]Ji-Kuns Aufwind", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Ji-Kun's Rising Winds] (1)\nSchmuck\n[q2]Erhöht Eure Waffenkundewertung um + 1.467.\nBenötigt Stufe 90\n[q2]Anlegen: Nahkampfangriffe, die Eure Gesundheit auf unter 35% verringern, führen dazu, dass Ihr sofort um 40341 geheilt werdet. Kann maximal einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94528] = {name = "[q4]Seelenbarriere", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Soul Barrier] (1)\nSchmuck\n+2.201 Ausdauer\nBenötigt Stufe 90\n[q2]Benutzen: Absorbiert jedes Mal, wenn Ihr körperlichen Schaden erleidet, bis zu 11206 Schaden. Absorbiert maximal bis zu ( 11206 * 5) Schaden. (2 Min Abklingzeit)\nVerkaufspreis:"}
