MultiLanguageItemData['de'][94530] = {name = "[q4]Blitz-verzauberter Kelch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Lightning-Imbued Chalice] (1)\nSchmuck\n+1.467 Intelligenz\nBenötigt Stufe 90\n[q2]Anlegen: Eure Heilzauber haben eine Chance, Euch 'Unendliche Macht' zu verleihen. Sobald 6 Aufladungen von 'Unendliche Macht' erreicht sind, heilt Ihr sofort das am schwersten verletzte Gruppenmitglied in der Nähe um 56025 Gesundheit. (Ungefähr 5.78 Auslösungen pro Minute)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94531] = {name = "[q4]Cha-Yes brillante Essenz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Cha-Ye's Essence of Brilliance] (1)\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 1.467.\nBenötigt Stufe 90\n[q2]Anlegen: Wenn Eure Zauber kritischen Schaden verursachen, besteht eine Chance, dass Eure Intelligenz 10 Sek. lang um 7333 erhöht wird. (Ungefähr 0.85 Auslösungen pro Minute)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94532] = {name = "[q4]Rune der Neuerschaffung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Rune of Re-Origination] (1)\nSchmuck\n+1.467 Beweglichkeit\nBenötigt Stufe 90\n[q2]Anlegen: Wenn Eure Angriffe treffen, besteht eine Chance, den Effekt 'Neuerschaffung' auszulösen. Dieser Effekt wandelt 10 Sek. lang den Wert der zwei niedrigsten aus Euren drei Attributen kritischer Trefferwert, Tempo und Meisterschaft zum höchsten dieser drei Attribute um und verdoppelt ihn außerdem. (Ungefähr 1.04 Auslösungen pro Minute, 10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][94535] = {name = "Gegrillter Dinosaurierschenkel", additional_info = "Benötigt Stufe 90\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 300000 Gesundheit und ( 75000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 200 Meisterschaft.\nVerkaufspreis:"}
MultiLanguageItemData['de'][94536] = {name = "Unbeschädigter Terrorhornbalg", additional_info = "Benötigt Stufe 90\n[q2]Benutzen: Tarnt Euch als ein Terrorhorn und verringert 10 Min. lang die Distanz, auf die Gegner Euch entdecken können, während Ihr Euch auf der Insel der Riesen befindet.\n[q]\"Sogar die Hörner sind noch dran!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][94552] = {name = "Pläne: Donnerstahlbarren", additional_info = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (500)\n[q2]Benutzen: Lehrt Euch die Herstellung von Donnerstahlbarren.\n[q2]Stellt einen Donnerstahlbarren aus Geistereisenbarren her. Dabei könnt Ihr zusätzliches Wissen über Geistereisen erlangen und einen Schmiedeplan entdecken, den Ihr noch nicht kennt. Dieser Vorgang kann nur einmal am Tag durchgeführt werden.\n\n\n[q3]Donnerstahlbarren\nWird beim Aufheben gebunden\n[q]\"Wird von Schmieden verwendet, um mächtige Objekte herzustellen.\"\nVerkaufspreis:\nBenötigt Geistereisenbarren (10)"}
