MultiLanguageItemData['de'][95456] = {name = "Beutel mit Scherwindkaktussamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft eine Handvoll Scherwindkaktussamen in den ausgewählten Zielbereich und streut sie auf bis zu 4 Beete gepflügten Erdreichs.\n10 Aufladungen\n[q]\"Der Scherwindkaktus ist mit Millionen feinster Nadeln bedeckt, die den vorbeiziehenden Wind filtern. Windwollfasern und Reste anderer Materialien bleiben häufig an ihnen hängen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][95457] = {name = "Beutel mit Raptorblattsamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft eine Handvoll Raptorblattsamen in den ausgewählten Zielbereich und streut sie auf bis zu 4 Beete gepflügten Erdreichs.\n10 Aufladungen\n[q]\"Das Raptorblatt ist eine fleischfressende Pflanze, der regelmäßig Shed-Ling, Falken und andere Kleintiere zum Opfer fallen. Nach einem einzigen Fang stirbt sie, setzt dabei ihre Samen frei und lässt oft auch Überreste ihrer Beute zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][95458] = {name = "Beutel mit Raptorblattsamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Wirft eine Handvoll Raptorblattsamen in den ausgewählten Zielbereich und streut sie auf bis zu 4 Beete gepflügten Erdreichs.\n10 Aufladungen\n[q]\"Das Raptorblatt ist eine fleischfressende Pflanze, der regelmäßig Shed-Ling, Falken und andere Kleintiere zum Opfer fallen. Nach einem einzigen Fang stirbt sie, setzt dabei ihre Samen frei und lässt oft auch Überreste ihrer Beute zurück.\"\nVerkaufspreis:"}
