MultiLanguageItemData['de'][95467] = {name = "[q2]Muster: Pracht des Leders", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (500)\n[q2]Benutzen: Lehrt Euch 'Pracht des Leders'.\nStellt einmal pro Tag einen prächtigen Balg aus nebelberührtem Leder her. Dabei könnt Ihr Euer Wissen über pandarische Lederverarbeitung vergrößern und ein neues Schnittmuster erlernen. Teilt eine Abklingzeit mit 'Pracht der Schuppen'.\n\n\n[q3]Prächtiger Balg\nVerkaufspreis: \nBenötigt Nebelberührtes Leder (20)"}
MultiLanguageItemData['de'][95468] = {name = "[q2]Muster: Pracht der Schuppen", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (500)\n[q2]Benutzen: Lehrt Euch 'Pracht der Schuppen'.\nStellt einmal pro Tag einen prächtigen Balg aus prismatischen Schuppen her. Dabei könnt Ihr Euer Wissen über pandarische Lederverarbeitung vergrößern und ein neues Schnittmuster erlernen. Teilt eine Abklingzeit mit 'Pracht des Leders'.\n\n\n[q3]Prächtiger Balg\nVerkaufspreis: \nBenötigt Prismatische Schuppe (20)"}
