MultiLanguageItemData['de'][97154] = {name = "Schlafsand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Wohlwollend\n[q2]Benutzen: Versetzt das Ziel 25 Sek. lang in einen magisch hervorgerufenen Schlaf. Funktioniert nur bei Humanoiden und Wildtieren während des Szenarios Schatzkammer des Donnerkönigs. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][97155] = {name = "Verwandlungsschlüssel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Ehrfürchtig\n[q2]Benutzen: Verformt mit Hilfe von Magie den Schlüssel, sodass er in jedes uralte Tor in der Zitadelle des Donnerkönigs im Szenario Schatzkammer des Donnerkönigs passt. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][97156] = {name = "Frostrunenfalle", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Respektvoll\n[q2]Benutzen: Platziert eine Rune, die das nächste gegnerische Ziel, das darauftritt, für 20 Sek. einfriert. Kann nur im Szenario Schatzkammer des Donnerkönigs eingesetzt werden. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][97157] = {name = "Trank des leichten Fußes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Freundlich\n[q2]Benutzen: Kann verwendet werden, um während des Szenarios Schatzkammer des Donnerkönigs über Bodenkachelfallen zu levitieren, mit verringerter Geschwindigkeit zu fallen und sich über Wasser zu bewegen. Erlittener Schaden bricht den Effekt ab. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][97158] = {name = "Ein gewöhnlicher Stein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Wohlwollend\n[q2]Benutzen: Kann verwendet werden, um im Szenario Schatzkammer des Donnerkönigs einen Gegner abzulenken oder eine Falle zu entschärfen. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][97159] = {name = "Arkaner Treibstoff", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (60)\nBenötigt Stufe 90\nBenötigtSonnenhäscheransturm\n- Respektvoll\n[q2]Benutzen: Verbraucht einen arkanen Fokus, um Euch vorwärts zu katapultieren. Kann nur während des Szenarios Schatzkammer des Donnerkönigs verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:"}
