MultiLanguageItemData['de'][102245] = {name = "[q5]Qian-Le, Mut von Niuzao", additional_info = "Wird beim Aufheben gebunden\nRücken\n1525 Rüstung\n+1.716 Beweglichkeit\n+2.694 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 918.\n[q2]Erhöht Eure Waffenkundewertung um + 918.\n[q2]Erhöht Eure Meisterschaftswertung um + 918.\n\n[q0]Roter Sockel\n[q0]Sockelbonus: + 90 Ausdauer\nBenötigt Stufe 90\n[q2]Anlegen: Die Ausdauer Niuzaos absorbiert den Schaden eines Angriffs, der Euch normalerweise umbringen würde, vollständig. Dieser Effekt hat eine Abklingzeit von 2 Min. Wirkt nicht bei Charakteren, die sich nicht in Schutzspezialisierung befinden."}
MultiLanguageItemData['de'][102246] = {name = "[q5]Xing-Ho, Atem von Yu'lon", additional_info = "Wird beim Aufheben gebunden\nRücken\n1525 Rüstung\n+2.694 Ausdauer\n+1.716 Intelligenz\n[q2]Erhöht Eure kritische Trefferwertung um + 918.\n[q2]Erhöht Eure Tempowertung um + 918.\n[q2]Erhöht Eure Meisterschaftswertung um + 918.\n\n[q0]Roter Sockel\n[q0]Sockelbonus: + 60 Intelligenz\nBenötigt Stufe 90\n[q2]Anlegen: Eure Schadenszauber haben eine Chance, Euch mit der Essenz von Yu'lon zu erfüllen, wodurch Ihr Jadedrachenfeuer auf das Ziel schleudert, was im Verlauf von 4 Sek. 1 Schaden verursacht. Dieser Schaden wirkt sich auch auf bis zu 5 weitere Gegner in der Nähe des brennenden Ziels aus. (Ungefähr 2.61 Auslösungen pro Minute)"}
MultiLanguageItemData['de'][102247] = {name = "[q5]Jina-Kang, Güte von Chi-Ji", additional_info = "Wird beim Aufheben gebunden\nRücken\n1525 Rüstung\n+2.694 Ausdauer\n+1.716 Intelligenz\n+918 Willenskraft\n[q2]Erhöht Eure Tempowertung um + 918.\n[q2]Erhöht Eure Meisterschaftswertung um + 918.\n\n[q0]Roter Sockel\n[q0]Sockelbonus: + 60 Intelligenz\nBenötigt Stufe 90\n[q2]Anlegen: Eure hilfreichen Zauber haben eine Chance, Euch den Geist von Chi-Ji zu verleihen, der 10 Sek. lang sämtliche Heilung um 5% erhöht und Eure überschüssige Heilung auf bis zu 5 verletzte Verbündete in der Nähe umverteilt. (Ungefähr 0.58 Auslösungen pro Minute)"}
