MultiLanguageItemData['de'][102463] = {name = "[q3]Eid des Feuerwächters", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verwandelt Euch in einen Feuerwächter von Ordos. Wenn Ihr in diesem Zustand andere Spielercharaktere tötet, besteht eine Chance, blutige Münzen zu erhalten. (1s Abklingzeit) (10 Min Abklingzeit)\n[q]\"Feuerwächter von Ordos tragen die Asche ihrer Opfer in einem besonderen Beutel mit sich herum, in dem sie weiterglüht.\""}
MultiLanguageItemData['de'][102464] = {name = "[q2]Schwarze Asche", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bedeckt den Gegner mit Asche und verringert so die auf ihn gewirkte Heilung 10 Sek. lang um 90%. Nur auf der Zeitlosen Insel verwendbar.\n[q]\"Die zu Asche zerfallenen Überreste eines Opfers für Ordos.\""}
MultiLanguageItemData['de'][102467] = {name = "[q3]Rauchbrenner der ewigen Pein", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Opfert 90% Eurer maximalen Gesundheit, um ein Abgesandter von Ordos zu werden. Während Ihr verwandelt seid, seid Ihr allen Spielercharakteren feindlich gesinnt und das Töten anderer Spielercharaktere gewährt blutige Münzen. Kann nur auf der Zeitlosen Insel verwendet werden und markiert Euch für den PvP-Kampf. (1s Abklingzeit) (1 Stunde Abklingzeit)\n[q]\"Ein rituelles Opfer ist erforderlich, um ein Anhänger von Ordos zu werden.\""}
