MultiLanguageItemData['de'][104047] = {name = "Glyphe 'Lautes Horn'", additional_info = "[q9]Erhebliche Glyphe\nKlassen: Todesritter\nBenötigt Stufe 25\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Horn des Winters' erzeugt jetzt 10 zusätzliche Runenmacht, die Abklingzeit wird jedoch um 100% erhöht.\nVerkaufspreis:"}
