MultiLanguageItemData['de'][186683] = {name = "Formel: Ring - Werte", additional_info = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenötigtDie Wächter der Sande\n- Respektvoll\n[q2]Benutzen: Lehrt Euch4 einen Ring dauerhaft so zu verzaubern4 dass er alle Werte um 4 erhöht.\n[q2]Einen Ring dauerhaft verzaubern, sodass alle Werte um 4 erhöht werden. Nur Ringe im Besitz des Verzauberers können verzaubert werden und dadurch wird der Ring seelengebunden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][187048] = {name = "[q3]Muster: Große Trommeln der Wiederherstellung", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (350)\nBenötigtKurenai\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch die Herstellung von Großen Trommeln der Wiederherstellung.\nVerkaufspreis:\n[q3]Große Trommeln der Wiederherstellung\nBenötigt Lederverarbeitung (350)\n[q2]Benutzen: Stellt im Verlauf von 15 Sek. 600 Gesundheit und Mana von Gruppenmitgliedern innerhalb von 40 Metern wieder her. Trommeln können in gestaltverändertem Zustand benutzt werden. Unwirksam bei Zielen der Stufe 80 oder höher. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppe (4)"}
MultiLanguageItemData['de'][187049] = {name = "[q3]Muster: Große Trommeln des Tempos", additional_info = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (345)\nBenötigtKurenai\n- Wohlwollend\n[q2]Benutzen: Lehrt Euch die Herstellung von Großen Trommeln des Tempos.\nVerkaufspreis:\n[q3]Große Trommeln des Tempos\nBenötigt Lederverarbeitung (340)\n[q2]Benutzen: Erhöht das Bewegungstempo von Gruppenmitgliedern innerhalb von 40 Metern um 15%. Hält 30 Sek. lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 Aufladungen\nVerkaufspreis:\nBenötigt Schweres Knotenhautleder (6), Windschuppen (4)"}
